// Win32-flavoured OgreVulkanBuildSettings.h — checked-in overlay.
//
// Ogre-Next generates this file from CMake/Templates/OgreVulkanBuildSettings.h.in
// at configure time, so a build tree inherits the *host's* platform choice. The
// Linux build tree under third_party/ogre-next-build/ therefore defines
// OGRE_VULKAN_WINDOW_XCB, and compiling RenderSystems/Vulkan/src/Windowing/win32/
// against it selects the wrong backend and fails.
//
// This overlay supplies the Win32 answer instead. Put it earlier on the include
// path than the build tree's include/ directory. It is for cross-compile
// validation of the Win32 translation units only — a real Windows build must let
// CMake generate the real file, which is why nothing in the build system points
// at this directory by default.
//
// Scope of the divergence, stated so this is not mistaken for a hack:
//   * OgreVulkanBuildSettings.h is the ONLY generated header whose contents
//     depend on the platform, and it depends on it in exactly one way: which of
//     the five OGRE_VULKAN_* symbols below is defined.
//   * OgreBuildSettings.h carries feature flags only (codecs, JSON, ZIP,
//     thread provider). Verified: no WIN32/LINUX/APPLE/ANDROID/PLATFORM define
//     appears in the generated Linux copy, so the same file is correct for both.
//   * OgreGL3PlusBuildSettings.h has the same shape as this one and would need
//     the same treatment before a GL3Plus Win32 TU is compiled.
//
// Drift is the failure mode of a checked-in copy of a generated file. It is
// guarded mechanically: `scripts/check-win32-headers.mjs` compares the symbol
// list below against the #cmakedefine list in the upstream template and fails if
// upstream adds, removes or renames a symbol. Run it in CI and after any pin
// bump; do not edit this file without running it.

#ifndef OGREVulkan_Custom_Config_H
#define OGREVulkan_Custom_Config_H

// CMake auto-generated configuration options

/* #undef OGRE_VULKAN_USE_SWAPPY */
/* #undef OGRE_VULKAN_WINDOW_NULL */
#define OGRE_VULKAN_WINDOW_WIN32
/* #undef OGRE_VULKAN_WINDOW_XCB */
/* #undef OGRE_VULKAN_WINDOW_ANDROID */

#endif
